CREATE TEMPORARY VIEW all_cheapest_${grass_region_without_quote} AS
select
     cspu_id
    ,item_id
    ,exp_tag
from(
    SELECT
         cspu_id
        ,item_id
    FROM srdi_mart.dim_sr_data_warehouse_pb_one_variation_model_analysis_hf
    WHERE grass_region = ${grass_region} AND local_date = ${local_date}
    group by
         cspu_id
        ,item_id
) a
lateral view explode(array('T1','T2')) b as exp_tag
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW dump_status_${grass_region_without_quote} AS
select -- dump的时候，有重复，要先去重（flink dump 的时候如果 instance 重试了，可能会写进去多条，按 cspu x item 随便取一条可以么？）
     item_id
    ,cspu_id
    ,pruning_tag
    ,is_valid
    ,filtered_reason
    ,case
       when pruning_tag in ('can_not_explore','obvious_bad') then 'non_preferred'
       when pruning_tag in ('obvious_good') then 'preferred' -- 一定要分开，先把purning tag的判断用完，在用explore_status，因为pruning_tag更准
       when explore_status='prefered'       then 'preferred'
       when explore_status='non_prefer'     then 'non_preferred'
       when explore_status in ('explore','invalid','prepare') then 'explore'
     end as exploration_status
    ,exp_tag
    ,version_date
    ,traffic_statistic_infos
from(
    SELECT
         *
        ,row_number() over (partition by exp_tag,item_id,cspu_id order by version_date desc) as rn
    FROM rcmd_feature.cheapest_v3_daily_status_info_df
    where grass_region in (${grass_region}) and grass_date = ${local_date}
) a
where a.rn=1 and pruning_tag is not null
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW pruning_info_${grass_region_without_quote} AS
SELECT
     exp_tag
    ,item_id
    ,cspu_id
    ,pruning_tag
    ,version_date
FROM srdi_mart.dwd_sr_data_warehouse_pb_rcmd_replace_pruning_v3_hf
where grass_region in (${grass_region}) and regional_date=${local_date}
and regional_hour = data_infra.max_pt('srdi_mart.dwd_sr_data_warehouse_pb_rcmd_replace_pruning_v3_hf', 'regional_hour', "grass_region=${grass_region} and regional_date=${local_date}")
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW tag_status_${grass_region_without_quote} AS
select
     a.item_id
    ,a.cspu_id
    ,a.exp_tag
    ,coalesce(b.pruning_tag,c.pruning_tag) as pruning_tag
    ,if(b.exploration_status is not null,b.exploration_status
       ,case
            when c.pruning_tag ='obvious_good' then 'preferred'
            when c.pruning_tag in ('obvious_bad','can_not_explore')  then 'non_preferred'
            when c.pruning_tag is null then 'prepare'
            else 'explore'
        end
      ) as exploration_status
    ,coalesce(b.version_date,c.version_date) as version_date
    ,traffic_statistic_infos
from all_cheapest_${grass_region_without_quote} a
left join dump_status_${grass_region_without_quote} b on a.cspu_id=b.cspu_id and a.item_id=b.item_id and a.exp_tag=b.exp_tag
left join pruning_info_${grass_region_without_quote} c on a.cspu_id=c.cspu_id and a.item_id=c.item_id and a.exp_tag=c.exp_tag
;
--sql_divide_splitter--

CREATE TEMPORARY VIEW item_tag_status_${grass_region_without_quote} AS
select
    item_id
   ,exp_tag
   ,split(max(exploration_status_concat),'#')[1] as item_exploration_status
from (
    select
        *
        ,case
          when exploration_status='preferred'        then concat('3#', exploration_status)
          when exploration_status='non_preferred'    then concat('2#', exploration_status)
          when exploration_status='explore'          then concat('1#', exploration_status)
          when exploration_status='prepare'          then concat('0#', exploration_status)
         end as exploration_status_concat
     from tag_status_${grass_region_without_quote}
) a
group by
    item_id
   ,exp_tag
;
--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_pb_rcmd_replace_status_v3_nd partition (grass_region = ${grass_region},local_date = ${local_date})
select
     a.exp_tag
    ,a.cspu_id
    ,a.item_id
    ,a.pruning_tag
    ,a.version_date
    ,a.exploration_status
    ,b.item_exploration_status
    ,a.traffic_statistic_infos[concat(a.exp_tag,'_S_EXPLORE_impr')] as explore_imp_cnt
    ,a.traffic_statistic_infos[concat(a.exp_tag,'_S_EXPLORE_clk')] as explore_click_cnt
    ,a.traffic_statistic_infos['C1_S_UNSPECIFIED_impr'] as cspu_imp_cnt
    ,a.traffic_statistic_infos['C1_S_UNSPECIFIED_clk'] as cspu_click_cnt
from tag_status_${grass_region_without_quote} a
left join item_tag_status_${grass_region_without_quote} b on a.item_id=b.item_id and a.exp_tag=b.exp_tag
;
